if(id==='bells'){if(!state.clock){toast('铜钟没有回应。先让中央古钟回到正确的时间。');return}if(state.bells){toast('月光之门已经打开，去东北角回家吧。');return}let sequence=[];show(`<div class="eyebrow">THE SONG OF HOME</div><h2>奏响归途</h2><p>三个音符，一段被遗忘的旋律。<br>想想笔记里的「低语、高歌、心间」。</p><div class="row"><button data-tone="0">Ⅰ · 低音</button><button data-tone="1">Ⅱ · 中音</button><button data-tone="2">Ⅲ · 高音</button></div><p class="clue" id="song">等待第一个音符…</p>`);document.querySelectorAll('[data-tone]').forEach(b=>b.onclick=()=>{let n=+b.dataset.tone;beep([262,330,392][n],.7);sequence.push(n);$('#song').textContent=sequence.map(x=>['低','中','高'][x]).join(' → ');if(sequence.length===3){if(sequence.join()==='0,2,1'){state.bells=true;close();sync();save();toast('钟声划破长夜。月光之门已经开启！')}else{sequence=[];$('#song').textContent='旋律散去了。再试一次：低 → 高 → 中。'}}})}
