function format(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(Math.floor(s%60)).padStart(2,'0')}function start(resume=false){if(resume){try{const s=JSON.parse(localStorage.getItem('midnight-ghost-v1'));if(s&&!s.won){Object.assign(state,s);ghost.position.set(s.x,.65,s.z);collectibles.forEach(c=>{c.taken=(c.type==='gear'?state.gearIds:state.memoryIds).includes(c.index);c.o.visible=!c.taken})}}catch{}}state.started=true;state.paused=false;$('#intro').hidden=true;sync();beep(523,.4);toast('找到三枚铜齿轮。靠近发光物品可拾取，靠近机关按 E。')}
function reset(){try{localStorage.removeItem('midnight-ghost-v1')}catch{}location.reload()}$('#start').onclick=()=>start();try{let s=JSON.parse(localStorage.getItem('midnight-ghost-v1'));if(s&&!s.won&&s.started){let b=document.createElement('button');b.className='primary';b.textContent='继续上次探索';b.style.marginRight='8px';b.onclick=()=>start(true);$('#start').before(b);$('#start').textContent='重新开始';}}catch{}
$('#interact').onclick=()=>interact();$('#sound').onclick=()=>{muted=!muted;$('#sound').textContent=muted?'♪̸':'♫';$('#sound').setAttribute('aria-label',muted?'开启声音':'关闭声音');if(!muted)beep()};$('#help').onclick=()=>show(`<div class="eyebrow">A GHOST'S FIELD GUIDE</div><h2>微光的冒险指南</h2><p>WASD / 方向键：沿画面方向移动<br>点击地面：移动到目的地<br>E：与附近机关互动<br>SPACE：长按幽灵穿梭，可穿蓝色栅栏并躲开守卫<br>Q：灵视，短暂照亮所有散落物<br>ESC：关闭窗口 / 暂停</p><p>靠近齿轮和记忆会自动拾取。守卫触碰会把你送回入口，但不会失去收集物。灵力会自行恢复。</p><p class="clue">路线：三枚齿轮 → 右侧机芯 → 中央古钟 → 三音钟 → 东北月光之门。<br>提示：古钟 03:15；旋律 低 → 高 → 中。</p><p class="small">进度自动保存在当前浏览器。</p>`);function pause(){if(!state.started||state.won)return;state.paused=!state.paused;$('#pause').textContent=state.paused?'▶':'Ⅱ';toast(state.paused?'已暂停 · 点击右上角 ▶ 继续':'继续探索');keys={}}$('#pause').onclick=pause;
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(modal.open)return;keys[e.key.toLowerCase()]=true;if(e.repeat)return;if(e.key.toLowerCase()==='e')interact();if(e.key.toLowerCase()==='q'&&state.started&&!state.paused&&!state.won&&state.energy>=20){state.energy-=20;vision=5;beep(820,.3);toast('灵视开启：光点标记了未收集的齿轮与记忆。')}if(e.key==='Escape')pause()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{keys={};phaseButton=false});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.started&&!state.won){state.paused=true;keys={};$('#pause').textContent='▶'}});
$('#phase').onpointerdown=e=>{phaseButton=true;$('#phase').setPointerCapture(e.pointerId)};$('#phase').onpointerup=$('#phase').onpointercancel=()=>phaseButton=false;document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{keys[b.dataset.key]=true;b.setPointerCapture(e.pointerId)};b.onpointerup=b.onpointercancel=()=>keys[b.dataset.key]=false});
const ray=new THREE.Raycaster(),plane=new THREE.Plane(new THREE.Vector3(0,1,0),0),hit=new THREE.Vector3();renderer.domElement.addEventListener('pointerdown',e=>{if(!state.started||modal.open)return;ray.setFromCamera(new THREE.Vector2(e.clientX/innerWidth*2-1,1-e.clientY/innerHeight*2),camera);if(ray.ray.intersectPlane(plane,hit)){target={x:Math.max(-13,Math.min(13,hit.x)),z:Math.max(-10.3,Math.min(10.3,hit.z))}}});
function canMove(x,z,phase,from){if(Math.abs(x)>13.2||z>10.5||z< -10.3)return false;if(!phase&&x>8.6&&x<13.5&&((z< -1.5)!==(from.z< -1.5)))return false;if(z< -1.5&&z> -6.5&&((x<8.9)!==(from.x<8.9)))return false;if(x>-2.8&&x<2.8&&z< -7.8)return false;return !obs.some(o=>!o.wall&&Math.hypot(x-o.x,z-o.z)<o.r+.35)}
let prev=performance.now(),saveTimer=0;function animate(now){requestAnimationFrame(animate);let dt=Math.min((now-prev)/1000,.05);prev=now;const t=now/1000;const active=state.started&&!state.paused&&!modal.open&&!state.won;let phase=false;if(active){state.seconds+=dt;saveTimer+=dt;if(saveTimer>5){save();saveTimer=0}phase=(keys[' ']||phaseButton)&&state.energy>1;state.energy=Math.max(0,Math.min(100,state.energy+(phase?-28:15)*dt));let dx=0,dz=0;let forward=(keys.w||keys.arrowup?1:0)-(keys.s||keys.arrowdown?1:0),side=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);if(forward||side){dx=side*.79-forward*.61;dz=-side*.61-forward*.79;target=null}else if(target){dx=target.x-ghost.position.x;dz=target.z-ghost.position.z;if(Math.hypot(dx,dz)<.15){target=null;dx=dz=0}}let len=Math.hypot(dx,dz);if(len){dx/=len;dz/=len;const speed=phase?6.4:4.2;let nx=ghost.position.x+dx*speed*dt,nz=ghost.position.z+dz*speed*dt;if(canMove(nx,ghost.position.z,phase,ghost.position))ghost.position.x=nx;if(canMove(ghost.position.x,nz,phase,ghost.position))ghost.position.z=nz;ghost.rotation.y=THREE.MathUtils.lerp(ghost.rotation.y,Math.atan2(dx,dz),.18)}
for(const c of collectibles){if(!c.taken&&Math.hypot(c.x-ghost.position.x,c.z-ghost.position.z)<.9){c.taken=true;c.o.visible=false;(c.type==='gear'?state.gearIds:state.memoryIds).push(c.index);beep(c.type==='gear'?660:880,.3);toast(c.type==='gear'?`拾取铜齿轮 ${state.gearIds.length}/3${state.gearIds.length===3?' · 去中央古钟右侧安装吧！':''}`:`找回记忆 ${state.memoryIds.length}/8 · ${['一阵熟悉的晚风。','窗边等候的身影。','温暖的灯光。','童年的摇篮曲。','雨后的青草香。','回家的那条小路。','被轻轻呼唤的名字。','原来，家一直在等你。'][c.index]}`);sync();save()}}
nearest=stations.filter(s=>Math.hypot(s.x-ghost.position.x,s.z-ghost.position.z)<2.15).sort((a,b)=>Math.hypot(a.x-ghost.position.x,a.z-ghost.position.z)-Math.hypot(b.x-ghost.position.x,b.z-ghost.position.z))[0];$('#interact').hidden=!nearest;if(nearest)$('#interact span').textContent=nearest.name;
sentinel.position.set(3+Math.sin(state.seconds*.32)*4,0,Math.cos(state.seconds*.32)*3);sentinel.rotation.y=-state.seconds*.32;invuln-=dt;if(!phase&&invuln<=0&&Math.hypot(ghost.position.x-sentinel.position.x,ghost.position.z-sentinel.position.z)<1.15){state.hits++;invuln=3;ghost.position.set(-2,.65,6);target=null;beep(110,.4);toast('被守钟灵发现！你回到了入口，收集物仍然保留。按住空格可以隐身躲开。')}vision=Math.max(0,vision-dt)}else{$('#interact').hidden=true}
if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('#toast').classList.remove('show')}document.body.classList.toggle('vision',vision>0);ghost.position.y=.62+Math.sin(t*2.5)*.12;ghostMat.opacity=phase?.35:.93;ghostLight.intensity=phase?5:3;shadow.position.set(ghost.position.x,.15,ghost.position.z);collectibles.forEach(c=>{c.o.rotation.y+=dt;c.o.position.y=1+Math.sin(t*2+c.index)*.15+(vision>0?.8:0);c.o.scale.setScalar(vision>0?1.45:1)});gears.forEach((g,i)=>{if(state.power&&active)g.rotation.z+=dt*(i%2?-.4:.3)});pendulum.rotation.z=Math.sin((state.paused?0:t)*1.5)*.28;candles.forEach((c,i)=>c.scale.y=1.3+Math.sin(t*8+i)*.3);$('#energyBar').style.width=state.energy+'%';$('#timer').textContent=format(state.seconds);renderer.render(scene,camera)}
function resize(){camera.aspect=innerWidth/innerHeight;const scale=Math.max(1,1.35/camera.aspect);camera.position.set(29*scale,32*scale,38*scale);camera.lookAt(0,0,0);camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}window.addEventListener('resize',resize);resize();sync();$('#loading').remove();requestAnimationFrame(animate);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_clocktower_progress',title:'查看钟楼探索进度',description:'Read current puzzle and collection progress without changing the game.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object');return {gears:state.gearIds.length,memories:state.memoryIds.length,power:state.power,clock:state.clock,bells:state.bells,won:state.won}}})).catch(()=>{})}catch{}}
